    {
      id: 3,
      title: 'Диван',
      img: 'sofa.jpg',
      desc: 'Lorem ipsum dolor sit amet, consectetur adipisicing.',
      category: 'sofa',
      price: '549.99'
    }
  ]);


  return (
    <div className="wrapper">
      <Header />
      <Footer />

    </div>
  );
}

export default App;
